import React from 'react';
import { FormattedMessage, useIntl } from 'react-intl';

import { Alert, PageHeader, StickyScrollWithFilters } from 'components';
import { WATCH_TOWER_FILTER_CATEGORIES } from 'components/Filter/config/filterCategories';
import { StickyNavigationTopOffsetProvider } from 'hooks';
import { usePageFilterApplied, usePageFilterData } from 'hooks/useFilters';
import { StyledGridContainer, StyledHomeContainer } from 'shared/Styles';
import { getPageTitleByKpi } from 'utils';
import { boldRichTextValues } from 'utils/i18n/richTextValues';

import {
  ContributionSection,
  WatchTowerExploreFurtherSection,
} from './components';
import {
  WATCH_TOWER_MAX_VISIBLE_FILTERS,
  WATCH_TOWER_NAVIGATION_TEST_ID,
  WATCH_TOWER_PAGE_NAME,
  WATCH_TOWER_VISIBLE_FILTER_FIELDS,
} from './constants';
import { useWatchTowerFilterMock } from './hooks/useWatchTowerFilterMock';
import { StyledWatchTowerContent } from './WatchTower.styles';

export const WatchTower = () => {
  const { formatMessage } = useIntl();
  const isFilterMockReady = useWatchTowerFilterMock();

  const { applied } = usePageFilterApplied(WATCH_TOWER_PAGE_NAME);
  const { dataFilters } = usePageFilterData(WATCH_TOWER_PAGE_NAME);

  const pageBreadcrumbTitle = formatMessage({
    id: 'ValueCreation.WatchTower.title',
  });

  if (!isFilterMockReady) {
    return null;
  }

  return (
    <>
      <StickyScrollWithFilters
        dataTestId={WATCH_TOWER_NAVIGATION_TEST_ID}
        filter={{
          pageName: WATCH_TOWER_PAGE_NAME,
          visibleFields: [...WATCH_TOWER_VISIBLE_FILTER_FIELDS],
          maxVisibleFilters: WATCH_TOWER_MAX_VISIBLE_FILTERS,
          hidden: false,
          filterCategories: WATCH_TOWER_FILTER_CATEGORIES,
        }}
        breadcrumbs={{
          pageList: [
            { href: '/value-creation', pageName: 'Value Creation' },
            {
              href: '/value-creation/watch-tower',
              pageName: pageBreadcrumbTitle,
            },
          ],
          showIcon: true,
        }}
        isResponsivePage
      />

      <StickyNavigationTopOffsetProvider
        navigationTestId={WATCH_TOWER_NAVIGATION_TEST_ID}
      >
        <StyledGridContainer isResponsivePage>
          <StyledHomeContainer>
            <PageHeader
              title={getPageTitleByKpi(dataFilters, applied)}
              subtitle={
                <FormattedMessage
                  id="ValueCreation.WatchTower.subtitle"
                  values={
                    boldRichTextValues as unknown as Record<
                      string,
                      React.ReactNode
                    >
                  }
                />
              }
              loading={false}
            />

            <StyledWatchTowerContent>
              <Alert
                type="neutral"
                emphasis="low"
                message={formatMessage({
                  id: 'ValueCreation.WatchTower.dataDisclaimer',
                  defaultMessage:
                    'Small variations may occur in data due to differences in local and global data sources, portfolio coverage, time periods and product scope.',
                })}
                dataTestId="watch-tower-disclaimer-alert"
              />
              <ContributionSection />
              <WatchTowerExploreFurtherSection />
            </StyledWatchTowerContent>
          </StyledHomeContainer>
        </StyledGridContainer>
      </StickyNavigationTopOffsetProvider>
    </>
  );
};
